-- Service: files  (per cell)
-- GENERATED by tools/split.py from plan/db/*.sql. Edit the source files or split.py, then re-run.
-- Load order: _prelude.sql, files.sql, _epilogue.sql
-- files first (doc_pages.cover points at it). Bytes live in object storage; row = metadata.
-- PROVEN: attachment host, category list, size, storage key, hidden flag.
-- ASSUMED: storage_key layout ws/{workspace_id}/{yyyy}/{file_id}; sha256 dedupe; scan status; presigned two-step upload.
CREATE TABLE files (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  storage_key text NOT NULL UNIQUE,
  filename text NOT NULL,
  mime_type text,
  size_bytes bigint NOT NULL DEFAULT 0 CHECK (size_bytes >= 0),
  sha256 bytea,
  category text NOT NULL DEFAULT 'other' CHECK (category IN
    ('images','videos','documents','pdfs','spreadsheets','presentations','audio','archives','code','other')),  -- PROVEN list
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','ready','quarantined','deleted')),
  uploaded_by uuid /* id -> identity.users */,
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  version integer NOT NULL DEFAULT 1
);

CREATE INDEX files_ws ON files (workspace_id, created_at DESC) WHERE deleted_at IS NULL;

-- storage browser / usage sum vs plan limit
CREATE INDEX files_sha ON files (workspace_id, sha256) WHERE sha256 IS NOT NULL;

-- dedupe on upload
CREATE INDEX files_pending ON files (created_at) WHERE status = 'pending';

-- 'what links to this task/doc'
CREATE TABLE file_previews (                         -- ASSUMED: thumbnails, pdf render, video poster
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  file_id uuid NOT NULL REFERENCES files(id) ON DELETE CASCADE,
  kind text NOT NULL CHECK (kind IN ('thumb_small','thumb_large','pdf','video_poster','text')),
  storage_key text NOT NULL,
  width integer,
  height integer,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','ready','failed')),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (file_id, kind)
);

CREATE INDEX file_previews_todo ON file_previews (created_at) WHERE status = 'pending';
